  background: #cdd6f4;
}

.widget-dnd > switch:checked {
  background: #f7768e;
}

.widget-dnd > switch slider {
  background: #0e0e16;
  border-radius: 12px;
}

.widget-dnd > switch:checked slider {
  background: #0e0e16;
  border-radius: 12px;
}

.widget-label {
  margin: 5px;
}

.widget-label > label {
  font-size: 1rem;
  color: #cdd6f4;
}

.widget-mpris {
  color: #cdd6f4;
  background: #0e0e16;
  padding: 3px 6px;
  margin: 5px;
