}

.inline-reply-entry {
  background: #0e0e16;
  color: #cdd6f4;
  caret-color: #cdd6f4;
  border: 1px solid #0e0e16;
  border-radius: 10px;
}

.inline-reply-button {
  font-size: 0.5rem;
  margin-left: 4px;
  background: #0e0e16;
  border: 1px solid #0e0e16;
  border-radius: 10px;
  color: #cdd6f4;
}

.inline-reply-button:disabled {
  background: initial;
  color: #cdd6f4;
  border: 1px solid transparent;
}

.inline-reply-button:hover {
  background: #0e0e16;
}

.body-image {
  margin-top: 6px;
  color: #cdd6f4;
  border-radius: 10px;
}

.summary {
  font-size: 0.9rem;
  /* font-weight: bold; */
  background: transparent;
  color: #cdd6f4;
  text-shadow: none;
}

.time {
  font-size: 0.8rem;
