}

.body {
  font-size: 0.8rem;
  /* font-weight: bold; */
  background: transparent;
  color: #cdd6f4;
  text-shadow: none;
}

.control-center {
  background: #0e0e16;
  border: 1px solid #0e0e16;
  color: #cdd6f4;
  border-radius: 10px;
}

.control-center-list {
  background: transparent;
}

.control-center-list-placeholder {
  opacity: 0.5;
}

.floating-notifications {
  background: transparent;
}

.blank-window {
  background: alpha(black, 0.1);
}

.widget-title {
  color: #cdd6f4;
  background: #0e0e16;
  padding: 3px 6px;
  margin: 5px;
  font-size: 1rem;
  border-radius: 10px;
}

.widget-title > button {
  font-size: 0.75rem;
  color: #cdd6f4;
  border-radius: 10px;
  background: transparent;
  border: 0.5px solid #0e0e16;
}

/* clear button */
.widget-title > button:hover {
  background: #cdd6f4;
  color: #d20f39;
}

.widget-dnd {
  background: #0e0e16;
  padding: 3px 6px;
  margin: 5px;
  border-radius: 12px;
  font-size: 0.5rem;
  color: #0e0e16;
}

.widget-dnd > switch {
  border-radius: 12px;
  /* border: 1px solid #00ffff; */
  background: #cdd6f4;
}

.widget-dnd > switch:checked {
  background: #f7768e;
}

.widget-dnd > switch slider {
  background: #0e0e16;
  border-radius: 12px;
}

.widget-dnd > switch:checked slider {
  background: #0e0e16;
  border-radius: 12px;
}

.widget-label {
  margin: 5px;
}

.widget-label > label {
  font-size: 1rem;
  color: #cdd6f4;
}

.widget-mpris {
  color: #cdd6f4;
  background: #0e0e16;
  padding: 3px 6px;
  margin: 5px;
  border-radius: 10px;
}

.widget-mpris > box > button {
  border-radius: 10px;
}

.widget-mpris-player {
  margin: 5px;
}

.widget-mpris-title {
  font-weight: 400;
  font-size: 1rem;
}

.widget-mpris-subtitle {
  font-size: 0.75rem;
}

.widget-buttons-grid {
  font-size: large;
  color: #0e0e16;
  padding: 2px;
  margin: 5px;
  border-radius: 10px;
  background: #0e0e16;
}

.widget-buttons-grid > flowbox > flowboxchild > button {
  margin: 1px;
  background: #0e0e16;
  border-radius: 10px;
  color: #cdd6f4;
}

/* individual buttons */
.widget-buttons-grid > flowbox > flowboxchild > button:hover {
  background: #cdd6f4;
  color: #0e0e16;
}

.widget-menubar > box > .menu-button-bar > button {
  border: none;
  background: transparent;
}

.topbar-buttons > button {
  border: none;
  background: transparent;
}

.notification.low progress,
.notification.normal progress {
  background-color: #00ffff;
  border-radius: 12.6px;
}

