/* SwayNC config  */

@import "colors.css";

@define-color noti-border-color @color12;
@define-color noti-bg #0e0e16;
@define-color noti-bg-alt #0e0e16;
@define-color noti-bg-hover #0e0e16;
@define-color text-color @foreground;

* {
  font-family: "JetBrains Mono Nerd Font";
  font-weight: bold;
  font-size: 1rem;
}

.control-center .notification-row:focus,
.control-center .notification-row:hover {
  opacity: 1;
  background: @background;
  border-radius: 10px;
}

.notification-row {
  outline: none;
}

.notification {
  /*color: #cdd6f4;*/
  background: alpha(@accent, .55);
  padding: 7px 7px 7px 0px;
  border-radius: 10px;
  border: 1px solid #0e0e16;
}

.notification-group {
  background-color: transparent;
  border-radius: 10px;
  /* border: 1px solid #cdd6f499; */
<|area_around_code_to_edit|>
}
.image {
  margin-right: 12px;
  margin-left: 15px;
  border-radius: 12px;
  padding: 0;
}

.close-button {
  background: transparent;
  color: @text;
  text-shadow: none;
  padding: 0;
<|code_to_edit|>
  border-radius: 10px;
  margin-top: 5px;
  margin-right: 5px;<|cursor|>
}

.close-button:hover {
  box-shadow: none;
  background: #f7768e;
<|/code_to_edit|>
  transition: all 0.15s ease-in-out;
  border: none;
}

.notification-action {
  border-top: none;
  border-radius: 10px;
  background: #0e0e16;
  color: #89dceb;
  padding: 0px; /* Reduce container padding */
<|/area_around_code_to_edit|>
  min-height: 0px; /* Remove GTK min height */
  min-width: 0px; /* Remove GTK min width */
}

.notification-action label {
  padding: 0px;
  margin: 0;
  font-size: 0.8rem;
  font-family: monospace;
  color: #89dceb;
}

.notification-default-action {
  margin: 0;
  padding: 0;
  font-size: 0.1rem;
  border-radius: 10px;
  background: #0e0e16;
}
.notification-default-action:hover,
.notification-action:hover {
  color: #cdd6f4;
  background: #0e0e16;
}

