@define-color selected        	    @primary;
@define-color accent                @tertiary;
@define-color text-alt              @surface;
@define-color hover           	    alpha(@selected, .55);
@define-color urgent          	    @error;


* {
  font-family: "JetBrains Mono Nerd Font";
  font-weight: bold;
  font-size: 1rem;
}

.control-center .notification-row:focus,
.control-center .notification-row:hover {
  opacity: 1;
  background: @background;
  border-radius: 10px;
}

.notification-row {
  outline: none;
}

.notification {
  /*color: #cdd6f4;*/
  background: alpha(@accent, .55);
  padding: 7px 7px 7px 0px;
  border-radius: 10px;
  border: 1px solid #0e0e16;
}

.notification-group {
  background-color: transparent;
  border-radius: 10px;
  /* border: 1px solid #cdd6f499; */
}
.image {
  margin-right: 12px;
  margin-left: 15px;
  border-radius: 12px;
  padding: 0;
}

.close-button {
  background: transparent;
  color: @text;
  text-shadow: none;
  padding: 0;
  border-radius: 10px;
  margin-top: 5px;
<|area_around_code_to_edit|>
  margin-right: 5px;
}

.close-button:hover {
  box-shadow: none;
  color: @text-alt;
  background-color: @primary;
  transition: all 0.15s ease-in-out;
  border: none;
}

.notification-action {
  border-top: none;
<|code_to_edit|>
  border-radius: 10px;
  background: alpha(@selected, .6);
  color: @text<|cursor|>;
