  text-shadow: none;
  padding: 0;
  border-radius: 10px;
  margin-top: 5px;
  margin-right: 5px;
}

.close-button:hover {
  box-shadow: none;
  color: @text-alt;
  background-color: @primary;
  transition: all 0.15s ease-in-out;
  border: none;
}

