@define-color accent-bg          @primary;
@define-color accent-fg          @on_primary;
@define-color text               @on_surface;
@define-color cyan               @tertiary;

* {
  all: unset;
  font-family: "GeistMono Nerd Font Propo";
  font-weight: bold;
  font-size: 14px;
  min-height: 0px;
  border-radius: 6px;
}

window#waybar {
  background: @background-beta;
  color: @text;
  border: 1px solid alpha(@border, 0.75);
  transition:
    background-color 0.25s linear,
    color 0.25s linear,
    border-color 0.5s linear;
}

#workspaces button,
#taskbar button {
  color: @text;
  margin: 6px;
  min-width: 15px;
  text-shadow:
    -1px -1px 2px @background,
    1px -1px 2px @background,
    -1px 1px 2px @background,
    1px 1px 2px @background;
  border: 1px solid transparent;
  transition: all 0.25s linear;
}

#workspaces button,
#taskbar button {
  padding: 4px;
}

#workspaces button.active,
#taskbar button.active,
#workspaces button.visible:not(.active) {
  background: @accent-bg;
  color: @accent-fg;
  text-shadow: none;
  border: 1px solid @background;
}

#workspaces button.visible:not(.active) {
  opacity: 0.5;
}

#workspaces button:hover,
#taskbar button:hover {
  opacity: 0.75;
  border: 1px solid @background;
}

#workspaces button:hover:not(.active),
#taskbar button:hover:not(.active):not(.maximized):not(.fullscreen) {
  border-color: @accent-bg;
}

#workspaces button.empty {
  opacity: 0.5;
}

#workspaces,
#taskbar {
  padding: 0 2px;
}

#taskbar button.maximized,
#taskbar button.fullscreen {
  border-color: @cyan;
}

#taskbar button.maximized.active,
#taskbar button.fullscreen.active {
  background: @cyan;
}

window#waybar.fullscreen {
  border-color: @cyan;
}

