}

#tray menu {
  background: @background-beta;
  box-shadow: none;
  margin: 2px;
  padding: 5px;
  border: 1px solid @border;
}

#tray menu menuitem {
  padding: 2px 20px 2px 20px;
  margin: 2px;
  border: 1px solid transparent;
  transition:
    background-color 0.1s,
    color 0.1s,
    border-color 0.1s,
    text-shadow 0.1s;
}

#tray menu menuitem:disabled label {
  opacity: 0.75;
}

#tray menu menuitem:hover:not(:disabled) {
