  margin: 2px;
}

.modules-left {
  margin-left: -4px;
}

.modules-right {
  margin-right: -4px;
}

#custom-menu {
  min-width: 30px; 
}

#pulseaudio,
#backlight,
#battery,
#network {
  min-width: 46px;
}


#cpu,
#memory,
#custom-pacman,
#custom-weather,
#custom-colorpicker{
  min-width: 24px;
}

