@import 			"../waybar/style/animated-waybar/launch_animation.css"; 
@import 			"colors.css";
@define-color background         @surface;
@define-color background-alpha   alpha(@surface, 0.25);
@define-color background-beta    alpha(@surface, 0.75);
@define-color border             @outline;
@define-color accent-bg          @primary;
@define-color accent-fg          @on_primary;
@define-color text               @on_surface;
@define-color cyan               @tertiary;

* {
  all: unset;
  font-family: "GeistMono Nerd Font Propo";
  font-weight: bold;
  font-size: 14px;
  min-height: 0px;
  border-radius: 6px;
}

window#waybar {
  background: @background-beta;
  color: @text;
  border: 1px solid alpha(@border, 0.75);
  transition:
    background-color 0.25s linear,
    color 0.25s linear,
    border-color 0.5s linear;
}

#workspaces button,
#taskbar button {
  color: @text;
  margin: 6px;
  min-width: 15px;
  text-shadow:
    -1px -1px 2px @background,
    1px -1px 2px @background,
    -1px 1px 2px @background,
    1px 1px 2px @background;
  border: 1px solid transparent;
  transition: all 0.25s linear;
}

#workspaces button,
#taskbar button {
  padding: 4px;
}

#workspaces button.active,
#taskbar button.active,
#workspaces button.visible:not(.active) {
  background: @accent-bg;
  color: @accent-fg;
  text-shadow: none;
  border: 1px solid @background;
}

#workspaces button.visible:not(.active) {
  opacity: 0.5;
}

#workspaces button:hover,
#taskbar button:hover {
  opacity: 0.75;
  border: 1px solid @background;
}

#workspaces button:hover:not(.active),
#taskbar button:hover:not(.active):not(.maximized):not(.fullscreen) {
  border-color: @accent-bg;
}

#workspaces button.empty {
  opacity: 0.5;
}

#workspaces,
#taskbar {
  padding: 0 2px;
}

#taskbar button.maximized,
#taskbar button.fullscreen {
  border-color: @cyan;
}

#taskbar button.maximized.active,
#taskbar button.fullscreen.active {
  background: @cyan;
}

window#waybar.fullscreen {
  border-color: @cyan;
}

window#waybar.fullscreen #window {
  background: @background;
  border-color: @cyan;
}

#waybar.fullscreen .module:not(.plugged):not(.charging):not(.Playing) {
  /* Uncomment this if needed */
  /* background: @background; */
}

#waybar.fullscreen #workspaces button:not(.active),
#waybar.fullscreen
  #taskbar
  button:not(.maximized):not(.fullscreen):not(:hover) {
  border-color: transparent;
}

#waybar.fullscreen #workspaces button:hover:not(.active),
#waybar.swallowing #workspaces button:hover:not(.active) {
  border-color: @accent-bg;
}

window#waybar.empty #window,
#taskbar.empty {
  border-color: transparent;
  background-color: transparent;
  opacity: 0;
  padding: 0;
  margin: 0;
}

window#waybar.swallowing #window {
  border-color: @tertiary;
}

.module {
  background: @background-alpha 0 0 / 750% 750%;
  color: @text;
  padding: 0 10px;
  margin: 0 4px;
  border: 1px solid @border;
  text-shadow:
    -1px -1px 2px @background,
    1px -1px 2px @background,
    -1px 1px 2px @background,
    1px 1px 2px @background;
  transition: all 0.25s linear;
}

.module:hover:not(#workspaces):not(#taskbar):not(#tray) {
  background: @accent-bg 0 0 / 750% 750%;
  color: @accent-fg;
  border: 1px solid @background;
  text-shadow: none;
}

#privacy {
  color: @surface;
  margin: 0 4px;
  padding: 0 10px;
  border: 1px solid @border;
  background-color: @error;
}

tooltip {
  margin: 2px;
  background: @background-beta;
  color: @text;
  border: 1px solid @border;
  text-shadow:
    -1px -1px 2px @background,
    1px -1px 2px @background,
    -1px 1px 2px @background,
    1px 1px 2px @background;
  box-shadow:
    -1px -1px 2px alpha(@border, 0.25),
    1px -1px 2px alpha(@border, 0.25),
    -1px 1px 2px alpha(@border, 0.25),
    1px 1px 2px alpha(@border, 0.25);
}

#tray menu {
  background: @background-beta;
  box-shadow: none;
  margin: 2px;
  padding: 5px;
  border: 1px solid @border;
}

#tray menu menuitem {
  padding: 2px 20px 2px 20px;
  margin: 2px;
  border: 1px solid transparent;
  transition:
    background-color 0.1s,
    color 0.1s,
    border-color 0.1s,
    text-shadow 0.1s;
}

#tray menu menuitem:disabled label {
  opacity: 0.75;
}

#tray menu menuitem:hover:not(:disabled) {
  background-color: @text;
  color: @accent-fg;
  text-shadow: none;
  border-color: @border;
  margin: 2px;
}

.modules-left {
  margin-left: -4px;
}

.modules-right {
  margin-right: -4px;
}

#custom-menu {
  min-width: 30px; 
}

#pulseaudio,
#backlight,
#battery,
#network {
  min-width: 46px;
}


#cpu,
#memory,
#custom-pacman,
#custom-weather,
#custom-colorpicker{
  min-width: 24px;
}

#custom-notification {
  min-width: 24px;
  font-size: 12px;
}

#custom-playerctl {
  min-width: 140px;
}

