    color: alpha(@outline,.3);
    border: none;
    text-shadow: 0px 0px 1.5px rgba(0, 0, 0, .2);
}
#workspaces button.empty:hover {
    color: alpha(@outline,.6);
    border: none;
    text-shadow: 0px 0px 1.5px @outline;
    transition: all 1s ease;
}
