    font-family: GeistMono Nerd Font Propo;
    font-size: 12px;
    min-height: 0;
}

/*------------Window--------------------*/
#window{
    background: @surface;
    padding-left: 15px;
    padding-right: 15px;
    border-radius: 16px;
    margin-top: 5px;
    margin-bottom: 5px;
    font-weight: normal;
    font-style: normal;
}

/*----------Waybar Window------------*/
window#waybar {
    background: @surface-alpha;
}

/*-----------Tooltip--------------*/
tooltip {
  background: @surface;
  border: 2px solid @tertiary;
  border-radius: 12px;
}
tooltip label {
  color: @on_surface;
  padding: 6px;
}

/*---------Workspaces-----------------*/
#workspaces {
    background: @surface;
    margin: 5px 5px;
    padding: 8px 5px;
    border-radius: 16px;
    color: @on_surface;
}
#workspaces button {
    font-weight: bold;
    padding: 0px 5px;
    margin: 0px 3px;
    border-radius: 16px;
    color: transparent;
    background: @surface_container_highest;
    transition: all 0.3s ease-in-out;
}

#workspaces button.active {
    font-weight: bold;
    background-color: @primary;
    color: @scrim;
    border-radius: 16px;
    min-width: 50px;
    background-size: 400% 400%;
    transition: all 0.3s ease-in-out;
}

#workspaces button:hover {
    font-weight: bold;
    background-color: @tertiary;
    color: @scrim;
    border-radius: 16px;
    min-width: 50px;
    background-size: 400% 400%;
}

#workspaces button.urgent {
    font-weight: bold;
    background-color: @error;
    color: @scrim;
    border-radius: 16px;
    min-width: 50px;
    background-size: 400% 400%;
    transition: all 0.3s ease-in-out;
}


/*-----------SwayNC & Weather------------*/
#custom-swaync, #custom-weather {
    font-weight: bold;
    background: @surface;
    margin: 5px; 
    padding: 8px 16px;
    color: @on_surface;
}
#custom-weather {
    border-radius: 24px 10px 24px 10px;
}
#custom-swaync {
    border-radius: 10px 24px 10px 24px;
}

/*---------------Tray, Clock, Playerctl, Battery, Cpu, Temperature, Colorpicker, Memory, Idle_inhibitor----------------------*/
#tray, #pulseaudio, #network, #battery, #cpu, #temperature, #custom-colorpicker, #memory, #custom-pacman, #idle_inhibitor,
#custom-playerctl.backward, #custom-playerctl.play, #custom-playerctl.foward{
    background: @surface;
    font-weight: bold;
    margin: 5px 0px;
}
#tray, #pulseaudio, #network, #battery{
    color: @on_surface;
    border-radius: 10px 24px 10px 24px;
    padding: 0 20px;
    margin-left: 7px;
}
