 *                                         
 */


/*------------Importing Matugen Colors---------------*/
@import "colors.css";


/*------------Global Properties-----------------*/
* {
    border: none;
    border-radius: 0px;
    font-family: GeistMono Nerd Font Propo;
    font-size: 12px;
    min-height: 0;
}

/*------------Window--------------------*/
#window{
    background: @surface;
    padding-left: 15px;
    padding-right: 15px;
    border-radius: 16px;
    margin-top: 5px;
    margin-bottom: 5px;
    font-weight: normal;
    font-style: normal;
}

/*----------Waybar Window------------*/
window#waybar {
    background: @surface-alpha;
}

/*-----------Tooltip--------------*/
tooltip {
  background: @surface;
  border: 2px solid @tertiary;
  border-radius: 12px;
}
tooltip label {
  color: @on_surface;
  padding: 6px;
}

/*---------Workspaces-----------------*/
#workspaces {
    background: @surface;
    margin: 5px 5px;
    padding: 8px 5px;
    border-radius: 16px;
    color: @on_surface;
}
#workspaces button {
    font-weight: bold;
    padding: 0px 5px;
    margin: 0px 3px;
    border-radius: 16px;
    color: transparent;
    background: @surface_container_highest;
    transition: all 0.3s ease-in-out;
}

#workspaces button.active {
    font-weight: bold;
    background-color: @primary;
    color: @scrim;
    border-radius: 16px;
    min-width: 50px;
    background-size: 400% 400%;
    transition: all 0.3s ease-in-out;
}

#workspaces button:hover {
    font-weight: bold;
    background-color: @tertiary;
    color: @scrim;
    border-radius: 16px;
    min-width: 50px;
    background-size: 400% 400%;
}

#workspaces button.urgent {
    font-weight: bold;
    background-color: @error;
    color: @scrim;
    border-radius: 16px;
    min-width: 50px;
    background-size: 400% 400%;
    transition: all 0.3s ease-in-out;
}


/*-----------SwayNC & Weather------------*/
#custom-swaync, #custom-weather {
    font-weight: bold;
    background: @surface;
    margin: 5px; 
    padding: 8px 16px;
    color: @on_surface;
}
#custom-weather {
    border-radius: 24px 10px 24px 10px;
}
#custom-swaync {
    border-radius: 10px 24px 10px 24px;
}

/*---------------Tray, Clock, Playerctl, Battery, Cpu, Temperature, Colorpicker, Memory, Idle_inhibitor----------------------*/
#tray, #pulseaudio, #network, #battery, #cpu, #temperature, #custom-colorpicker, #memory, #custom-pacman, #idle_inhibitor,
#custom-playerctl.backward, #custom-playerctl.play, #custom-playerctl.foward{
    background: @surface;
    font-weight: bold;
    margin: 5px 0px;
}
#tray, #pulseaudio, #network, #battery{
    color: @on_surface;
    border-radius: 10px 24px 10px 24px;
    padding: 0 20px;
    margin-left: 7px;
}
#clock {
    color: @on_surface;
    background: @surface;
    border-radius: 0px 0px 0px 40px;
    padding: 10px 10px 15px 25px;
    margin-left: 7px;
    font-weight: bold;
    font-size: 14px;
}

#tray menu * {
    padding: 0px 5px;
    transition: all .3s ease; 
}

#tray menu separator {
    padding: 0px 5px;
    transition: all .3s ease; 
}


/*-----------Playerctl-------------------*/
#custom-playerctl.backward, #custom-playerctl.play, #custom-playerctl.foward {
    background: @surface;
    font-size: 22px;
}
#custom-playerctl.backward:hover, #custom-playerctl.play:hover, #custom-playerctl.foward:hover{
    color: @on_surface;
}
#custom-playerctl.backward {
    color: @tertiary;
    border-radius: 24px 0px 0px 10px;
    padding-left: 16px;
    margin-left: 7px;
}
#custom-playerctl.play {
    color: @on_primary_fixed_variant;
    padding: 0 5px;
}
#custom-playerctl.foward {
    color: @tertiary;
    border-radius: 0px 10px 24px 0px;
    padding-right: 12px;
    margin-right: 7px
}
#custom-playerlabel {
    background: @surface;
    color: @on_surface;
    padding: 0 20px;
    border-radius: 24px 10px 24px 10px;
    margin: 5px 0;
    font-weight: bold;
}

/*-----------Group--------------*/
#group-utility {
    padding: 0px 5px;
    transition: all .3s ease; 
}



/*-------------Launcher--------------*/
#custom-launcher {
    color: @on_tertiary_container;
    background: @surface;
    margin: 0px 5px 0px 0px;
    padding: 0px 35px 0px 15px;
    border-radius: 0px 0px 40px 0px;
    font-size: 28px;
}

/*--------------Cpu, Termperature, Colorpicker, Memory, Idle_inhibitor----------------*/
#custom-colorpicker, #cpu, #temperature, #memory, #custom-pacman,#idle_inhibitor {
    background: @surface;
    font-size: 16px;
}

#cpu {
    color: @tertiary;
}

#memory {
    color: @primary;
}

#temperature {
    color: @tertiary;
}

#custom-pacman {
    color: @primary;
}

#idle_inhibitor {
    color: @on_surface;
}

#idle_inhibitor.activated {
    color: @error;
}

#cpu {
    color: @tertiary;
    border-radius: 24px 0px 0px 10px;
    padding-left: 16px;
    padding-right: 7px;
    margin-left: 7px;
}

#temperature, #memory, #custom-pacman, #idle_inhibitor {
    padding-left: 7px;
    padding-right: 7px;
}

#custom-colorpicker {
    color: @tertiary;
    border-radius: 0px 10px 24px 0px;
    padding-right: 12px;
    padding-left: 7px;
    margin-right: 7px
}

/*---------------Expand---------------*/
#custom-expand {
    background: transparent;
    color: @on_surface;
    margin: 1px;
    font-size: 22px;
}

#custom-expand:hover {
    color: @primary;
}

custom-cava_mviz {
