    font-family: GeistMono Nerd Font Propo;
    font-weight: bold;
}
window#waybar{
    all:unset;
}
.modules-left {
    padding: 7px;
    margin: 10px 0px 5px 10px;
    border-radius: 10px;
    background: alpha(@background,.6);
    box-shadow: 0px 0px 2px rgba(0, 0, 0, .6);
}
.modules-center {
    padding: 7px;
    margin: 10px 0px 5px 0px;
    border-radius: 10px;
    background: alpha(@background,.6);
    box-shadow: 0px 0px 2px rgba(0, 0, 0, .6);
}
.modules-right {
    padding:7px;
    margin: 10px 10px 5px 0px;
    border-radius: 10px;
    background: alpha(@background,.6);
    box-shadow: 0px 0px 2px rgba(0, 0, 0, .6);
}
tooltip {
    background: @background;
    border: 2px solid @primary;
    border-radius: 12px;
}
tooltip-label {
    color: @on_surface;
    padding: 5px;
}


#custom-notification {
    padding: 0px 5px;
    transition: all .3s ease;
    color: @on_surface;
}

#clock{
    padding: 0px 5px;
    color: @on_surface;
    transition: all .3s ease;
}

#temperature {
    padding: 0px 5px;
    transition: all .3s ease; 
    color: @primary;

}

/* #clock:hover, #custom-pacman:hover, #custom-notification:hover,#bluetooth:hover,#network:hover,#battery:hover, #cpu:hover,#memory:hover,#temperature:hover{
    transition: all .3s ease;
    color: @primary;
} */

#custom-pacman{
    padding: 0px 5px;
    transition: all .3s ease;
    color: @on_surface;

}
#workspaces {
    padding: 0px 5px;
}
#workspaces button {
    all:unset;
    padding: 0px 5px;
    color: alpha(@primary,.3);
    transition: all .2s ease;
}
#workspaces button:hover {
    color: alpha(@primary,.6);
    border: none;
    text-shadow: 0px 0px 1.5px @primary_fixed_dim;
    transition: all 1s ease;
}
#workspaces button.active {
    color: @primary;
    border: none;
    text-shadow: 0px 0px 3px @primary_fixed_dim;
}
#workspaces button.empty {
    color: alpha(@outline,.3);
    border: none;
    text-shadow: 0px 0px 1.5px rgba(0, 0, 0, .2);
}
#workspaces button.empty:hover {
    color: alpha(@outline,.6);
    border: none;
    text-shadow: 0px 0px 1.5px @outline;
    transition: all 1s ease;
}
#workspaces button.empty.active {
    color: @primary;
    border: none;
    text-shadow: 0px 0px 2px @primary_fixed_dim;
}
#bluetooth{
    padding: 0px 5px;
    transition: all .3s ease;
    color: @on_surface;

}
#network{
    padding: 0px 5px;
    transition: all .3s ease;
    color: @on_surface;

}

#custom-weather {
    padding: 0px 5px;
    transition: all .3s ease;
    color: @on_surface;
}

#battery{
    padding: 0px 5px;
    transition: all .3s ease;
    color: @on_surface;
}
#battery.charging {
    color: @primary;
}

#battery.warning:not(.charging) {
    color: @error;
}

#battery.critical:not(.charging) {
    color: @on_error_container;
    background-color: @error_container;
    animation-name: blink;
    animation-duration: 0.5s;
    animation-timing-function: linear;
    animation-iteration-count: infinite;
    animation-direction: alternate;
}
#group-expand{
    padding: 0px 5px;
    transition: all .3s ease; 
}
#custom-expand{
    padding: 0px 5px;
    color: alpha(@primary,.2);
    text-shadow: 0px 0px 2px rgba(0, 0, 0, .7);
    transition: all .3s ease; 
}
#custom-expand:hover{
    color: @primary;
    text-shadow: 0px 0px 3px @primary_fixed_dim;
}
#custom-colorpicker{
    padding: 0px 5px;
}
#cpu,#memory,#temperature{
    padding: 0px 5px;
    transition: all .3s ease; 
    color: @on_surface;

}
#custom-endpoint{
    color:transparent;
    text-shadow: 0px 0px 1.5px rgba(0, 0, 0, 1);

}
#tray{
    padding: 0px 5px;
    transition: all .3s ease; 

}
#tray menu * {
    padding: 0px 5px;
    transition: all .3s ease; 
}

#tray menu separator {
    padding: 0px 5px;
    transition: all .3s ease; 
