/* Center the action buttons row inside notifications. This targets
   common possible container classnames used by SwayNC and keeps the
   change minimal: it uses flexbox to center children and removes
   extra horizontal margins from the buttons. */
.notification .notification-actions,
.notification .actions,
.notification .action-row {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
}

.notification .notification-action,
.notification .notification-default-action {
  margin-left: 0;
  margin-right: 0;
}

/* Also target GTK container widgets (flowbox / box) used inside notifications
   so we center children regardless of the specific container element name. */
.notification > flowbox,
.notification flowbox,
.notification > box,
.notification box {
  display: flex;
  justify-content: center;
  align-items: center;
  gap: 8px;
  width: 100%;
}

