.notification-action {
  border-top: none;
  border-radius: 10px;
  background: alpha(@surface_container, 0.8);
  color: @primary;
  padding: 8px 12px;
  min-height: 0px;
  min-width: 0px;
  margin: 5px;
  border: 1.5px solid alpha(@primary, 0.5);
  transition: all 0.2s ease-in-out;
}

.notification-action label {
  padding: 0px;
  margin: 0;
  font-size: 0.9rem;
  font-weight: 600;
  font-family: "JetBrains Mono Nerd Font";
  color: @primary;
}

